class Widget {};

// Factory returns a unique_ptr, giving caller ownership choice
std::unique_ptr<Widget> makeWidget() {
    return std::make_unique<Widget>();
}

void run() {
    auto u_ptr = makeWidget(); // u_ptr has exclusive ownership

    // Upgrade to shared ownership. This is a one-way transfer.
    std::shared_ptr<Widget> s_ptr1 = std::move(u_ptr);
    // u_ptr is now null

    std::cout << "s_ptr1 use_count: " << s_ptr1.use_count() << std::endl; // 1

    // Create another shared_ptr, increasing the reference count
    std::shared_ptr<Widget> s_ptr2 = s_ptr1;
    std::cout << "s_ptr1 use_count: " << s_ptr1.use_count() << std::endl; // 2

    // Cannot transfer ownership back to a unique_ptr
    // std::unique_ptr<Widget> u_ptr2 = s_ptr1; // Compile error
}
